#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);assets=File.join(client,'assets');metas=Dir.glob(File.join(assets,'**/*.meta')).sort;uuids={};parse=[];orphans=[]
metas.each do|p|begin;d=JSON.parse(File.read(p));u=d['uuid'];(uuids[u]||=[])<<p.delete_prefix(client+'/') if u;rescue=>e;parse<<{path:p.delete_prefix(client+'/'),error:e.message};end;source=p.sub(/\.meta\z/,'');orphans<<p.delete_prefix(client+'/') unless File.exist?(source);end
duplicates=uuids.select{|k,v|k&&v.length>1};missing=Dir.glob(File.join(assets,'**/*'),File::FNM_DOTMATCH).reject{|p|p.delete_prefix(assets+'/').split('/').any?{|part|part.start_with?('.')}}.select{|p|File.basename(p)!~ /\A\.{1,2}\z/&&!p.end_with?('.meta')&&!File.exist?(p+'.meta')}.map{|p|p.delete_prefix(client+'/')};refs=JSON.parse(File.read(File.join(root,'work/audit/cocos-uuid-reference-audit.json')));checks={metaParseErrors:parse.empty?,uniqueUuids:duplicates.empty?,noOrphanMeta:orphans.empty?,allAssetSourcesHaveMeta:missing.empty?,noMissingDirectReferences:refs.dig('summary','missingDirectReferences').to_i.zero?};report={schemaVersion:1,metaFiles:metas.length,uuidCount:uuids.length,checks:checks,duplicates:duplicates,parseErrors:parse,orphanMeta:orphans,missingMeta:missing,referenceAudit:refs['summary']};out=File.join(root,'docs/generated/creal08-meta-integrity.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");tasks=File.join(root,'docs/Aoo-前后端全框架功能通信审计任务清单.md');text=File.read(tasks);status=checks.values.all? ? '已完成':'失败跳过';result=checks.values.all? ? '已完成':'阻塞';reference_count=refs.dig('summary','directReferences').to_i;detail=checks.values.all? ? "当前 #{metas.length} 个 Meta 已完成 JSON 解析、UUID 唯一、源资源配对、孤儿/缺失及 #{reference_count} 条直接引用闭包验证，全部通过。" : "已完成当前 #{metas.length} 个 Meta 全量审计；未通过项：#{checks.reject{|_,v|v}.keys.join('、')}，精确清单已记录后跳过。";text.sub!(/^\| CREAL08 \|.*$/,"| CREAL08 | #{status} | 全量 Meta | #{result} | #{detail} 证据：docs/generated/creal08-meta-integrity.json、work/audit/cocos-uuid-reference-audit.json |") or abort 'CREAL08 row missing';File.write(tasks,text);puts "CREAL08 AUDITED: #{status}"
